    16→
    17→use anyhow::{Context, Result};
    18→use clap::{Parser, Subcommand};
    19→use flate2::read::GzDecoder;
    20→use serde::Deserialize;
    21→use std::env;
    22→use std::fs;
    23→#[cfg(unix)]
    24→use std::os::unix::fs::PermissionsExt;
    25→#[cfg(unix)]
    26→use std::os::unix::process::CommandExt;
    27→use std::path::PathBuf;
    28→use std::process::{Command, Stdio};
    29→use tar::Archive;
    30→use walkdir::WalkDir;
    31→
    32→#[derive(Parser)]
    33→#[command(name = "pr-builds")]
    34→#[command(about = "Manage PR builds for Spice.ai", long_about = None)]
    35→struct Cli {
    36→    #[command(subcommand)]
    37→    command: Commands,
    38→}
    39→
    40→#[derive(Subcommand)]
    41→enum Commands {
    42→    /// Trigger a build for the current (or specified) branch.
    43→    ///
    44→    /// Triggers the '`build_and_release`' workflow in GitHub Actions.
    45→    /// If an active build exists for the latest commit (SHA-based), it will be reused.
    46→    /// If a successful build exists (for this commit), no action is taken.
    47→    Trigger {
    48→        /// Branch to trigger build for. Defaults to current branch.
    49→        #[arg(short, long)]
    50→        branch: Option<String>,
    51→
    52→        /// PR number to resolve to a branch.
    53→        #[arg(short, long)]
    54→        pr: Option<u64>,
    55→
    56→        /// Wait for the build to complete.
    57→        ///
    58→        /// If an existing build is reused, this will wait for that build.
    59→        #[arg(short, long)]
    60→        wait: bool,
    61→    },
    62→    /// Install the latest binary for the current (or specified) branch.
    63→    ///
    64→    /// Downloads and installs the 'spiced' binary from the latest successful
    65→    /// GitHub Actions run for the branch.
    66→    Install {
    67→        /// Branch to install binary for. Defaults to current branch.
    68→        #[arg(short, long)]
    69→        branch: Option<String>,
    70→
    71→        /// PR number to resolve to a branch.
    72→        #[arg(short, long)]
    73→        pr: Option<u64>,
    74→    },
    75→    /// Run the binary for the current (or specified) branch.
    76→    ///
    77→    /// If the binary is not installed locally, it will be automatically downloaded
    78→    /// and installed from the latest successful build.
    79→    Run {
    80→        /// Branch to run binary for. Defaults to current branch.
    81→        #[arg(short, long)]
    82→        branch: Option<String>,
    83→
    84→        /// PR number to resolve to a branch.
    85→        #[arg(short, long)]
    86→        pr: Option<u64>,
    87→
    88→        /// Interactive mode: select a branch from installed binaries
    89→        #[arg(short, long)]
    90→        interactive: bool,
    91→
    92→        /// Arguments to pass to spiced
    93→        #[arg(last = true)]
    94→        args: Vec<String>,
    95→    },
    96→}
    97→
    98→#[derive(Deserialize, Debug)]
    99→struct GhRun {
   100→    #[serde(rename = "databaseId")]
   101→    database_id: u64,
   102→}
   103→
   104→#[derive(Deserialize, Debug)]
   105→struct GhPr {
   106→    #[serde(rename = "headRefName")]
   107→    head_ref_name: String,
   108→}
   109→
   110→#[derive(Deserialize)]
   111→struct GhRepo {
   112→    #[serde(rename = "nameWithOwner")]
   113→    name_with_owner: String,
   114→}
   115→
   116→#[cfg(unix)]
   117→fn main() -> Result<()> {
   118→    let cli = Cli::parse();
   119→
   120→    match &cli.command {
   121→        Commands::Trigger { branch, pr, wait } => trigger_build(branch.as_deref(), *pr, *wait),
   122→        Commands::Install { branch, pr } => install_build(branch.as_deref(), *pr),
   123→        Commands::Run {
   124→            branch,
   125→            pr,
   126→            interactive,
   127→            args,
   128→        } => run_build(branch.as_deref(), *pr, *interactive, args),
   129→    }
   130→}
   131→
   132→#[cfg(not(unix))]
   133→fn main() -> Result<()> {
   134→    anyhow::bail!("This tool is currently only supported on Unix-like systems.");
   135→}
   136→
   137→#[cfg(unix)]
   138→fn resolve_branch_or_pr(branch: Option<&str>, pr: Option<u64>) -> Result<String> {
   139→    if let Some(b) = branch {
   140→        return Ok(b.to_string());
   141→    }
   142→
   143→    if let Some(pr_num) = pr {
   144→        println!("Resolving PR #{pr_num} to branch...");
   145→        let output = Command::new("gh")
   146→            .args(["pr", "view", &pr_num.to_string(), "--json", "headRefName"])
   147→            .output()
   148→            .context("Failed to execute gh pr view")?;
   149→
   150→        if !output.status.success() {
   151→            anyhow::bail!(
   152→                "Failed to resolve PR #{}: {}",
   153→                pr_num,
   154→                String::from_utf8_lossy(&output.stderr)
   155→            );
   156→        }
   157→
   158→        let pr_data: GhPr = serde_json::from_slice(&output.stdout)?;
   159→        println!(
   160→            "Resolved PR #{} to branch '{}'",
   161→            pr_num, pr_data.head_ref_name
   162→        );
   163→        return Ok(pr_data.head_ref_name);
   164→    }
   165→
   166→    get_current_branch()
   167→}
   168→
   169→#[cfg(unix)]
   170→fn get_current_branch() -> Result<String> {
   171→    let output = Command::new("git")
   172→        .args(["branch", "--show-current"])
   173→        .output()
   174→        .context("Failed to execute git command")?;
   175→
   176→    if !output.status.success() {
   177→        anyhow::bail!("git branch --show-current failed");
   178→    }
   179→
   180→    let branch = String::from_utf8(output.stdout)
   181→        .context("Branch name is not valid UTF-8")?
   182→        .trim()
   183→        .to_string();
   184→
   185→    if branch.is_empty() {
   186→        anyhow::bail!("Could not determine current branch");
   187→    }
   188→    Ok(branch)
   189→}
   190→
   191→fn validate_branch_name(branch: &str) -> Result<()> {
   192→    if branch.is_empty() {
   193→        anyhow::bail!("Branch name cannot be empty");
   194→    }
   195→    if branch.contains("..") {
   196→        anyhow::bail!("Branch name cannot contain '..'");
   197→    }
   198→    if branch.starts_with('/') || branch.contains(':') {
   199→        anyhow::bail!("Branch name contains invalid characters");
   200→    }
   201→    Ok(())
   202→}
   203→
   204→#[cfg(unix)]
   205→fn get_repo_owner_name() -> Result<String> {
   206→    let output = Command::new("gh")
   207→        .args(["repo", "view", "--json", "nameWithOwner"])
   208→        .output()
   209→        .context("Failed to determine current repository via gh repo view")?;
   210→
   211→    if !output.status.success() {
   212→        anyhow::bail!(
   213→            "gh repo view failed: {}",
   214→            String::from_utf8_lossy(&output.stderr)
   215→        );
   216→    }
   217→
   218→    let gh_repo: GhRepo =
   219→        serde_json::from_slice(&output.stdout).context("Failed to parse gh repo view output")?;
   220→    Ok(gh_repo.name_with_owner)
   221→}
   222→
   223→#[cfg(unix)]
   224→fn trigger_build(branch: Option<&str>, pr: Option<u64>, wait: bool) -> Result<()> {
   225→    let branch = resolve_branch_or_pr(branch, pr)?;
   226→    validate_branch_name(&branch)?;
   227→    let repo_owner_name = get_repo_owner_name()?;
   228→
   229→    // Get the latest commit SHA for the branch
   230→    println!("Fetching latest commit SHA for branch '{branch}'...");
   231→    let output = Command::new("gh")
   232→        .args([
   233→            "api",
   234→            &format!("repos/{repo_owner_name}/branches/{branch}"),
   235→            "--jq",
   236→            ".commit.sha",
   237→        ])
   238→        .output()
   239→        .context("Failed to fetch branch SHA")?;
   240→
   241→    if !output.status.success() {
   242→        anyhow::bail!(
   243→            "Failed to get branch SHA: {}",
   244→            String::from_utf8_lossy(&output.stderr)
   245→        );
   246→    }
   247→
   248→    let latest_sha = String::from_utf8(output.stdout)?.trim().to_string();
   249→    println!("Latest SHA: {latest_sha}");
   250→
   251→    // Check for existing runs for this SHA
   252→    println!("Checking for existing builds for this SHA...");
   253→    let output = Command::new("gh")
   254→        .args([
   255→            "run",
   256→            "list",
   257→            "--workflow",
   258→            "build_and_release.yml",
   259→            "--branch",
   260→            &branch,
   261→            "--limit",
   262→            "5", // Check a few recent runs
   263→            "--json",
   264→            "databaseId,headSha,status,conclusion",
   265→        ])
   266→        .output()
   267→        .context("Failed to list recent runs")?;
   268→
   269→    let mut existing_run_id: Option<u64> = None;
   270→    let mut max_seen_id: u64 = 0;
   271→
   272→    if output.status.success() {
   273→        let runs: Vec<serde_json::Value> = serde_json::from_slice(&output.stdout)?;
   274→        for run in runs {
   275→            if let Some(id) = run["databaseId"].as_u64()
   276→                && id > max_seen_id
   277→            {
   278→                max_seen_id = id;
   279→            }
   280→
   281→            if let Some(run_sha) = run["headSha"].as_str()
   282→                && run_sha == latest_sha
   283→            {
   284→                // Found a run for the same SHA
   285→                let status = run["status"].as_str().unwrap_or("");
   286→                let conclusion = run["conclusion"].as_str().unwrap_or("");
   287→                let id = run["databaseId"].as_u64();
   288→
   289→                if let Some(id) = id {
   290→                    if status == "completed" && conclusion == "success" {
   291→                        println!(
   292→                            "Found successful build for this SHA (Run ID: {id}). No need to trigger.",
   293→                        );
   294→                        return Ok(());
   295→                    } else if status != "completed" {
   296→                        println!("Found active build for this SHA (Run ID: {id}). Reusing it.",);
   297→                        existing_run_id = Some(id);
   298→                        break;
   299→                    }
   300→
   301→                    println!(
   302→                        "Found failed/cancelled build for this SHA (Run ID: {id}). Retrying...",
   303→                    );
   304→                    // If failed, we probably want to trigger a new one, so continue loop or stop?
   305→                    // Default behavior: trigger new if latest is failed.
   306→                }
   307→            }
   308→        }
   309→    }
   310→
   311→    let run_id_to_watch = if let Some(id) = existing_run_id {
   312→        id
   313→    } else {
   314→        println!("No active build found for latest SHA. Triggering new build...");
   315→
   316→        let platform_option = {
   317→            let os = env::consts::OS;
   318→            let arch = env::consts::ARCH;
   319→            match (os, arch) {
   320→                ("linux", "aarch64") => "Linux aarch64".to_string(),
   321→                ("linux", "x86_64") => "Linux x64".to_string(),
   322→                ("macos", "aarch64") => "macOS aarch64 (Apple Silicon)".to_string(),
   323→                ("macos", "x86_64") => {
   324→                    anyhow::bail!(
   325→                        "Failed to determine build platform for OS macOS and architecture x86_64: Intel macOS is not supported by the build_and_release workflow. Use an Apple Silicon macOS or supported Linux machine to trigger this build."
   326→                    );
   327→                }
   328→                (other_os, other_arch) => {
   329→                    anyhow::bail!(
   330→                        "Failed to determine build platform for OS {other_os} and architecture {other_arch}: Unsupported combination for build_and_release workflow. Supported combinations are: linux/aarch64, linux/x86_64, macos/aarch64.",
   331→                    );
   332→                }
   333→            }
   334→        };
   335→
   336→        println!("Requesting platform: {platform_option}");
   337→
   338→        let status = Command::new("gh")
   339→            .args([
   340→                "workflow",
   341→                "run",
   342→                "build_and_release.yml",
   343→                "--ref",
   344→                &branch,
   345→                "-f",
   346→                &format!("platform_option={platform_option}"),
   347→            ])
   348→            .status()
   349→            .context("Failed to execute gh workflow run")?;
   350→
   351→        if !status.success() {
   352→            anyhow::bail!("Failed to trigger build");
   353→        }
   354→
   355→        println!("Build triggered successfully.");
   356→
   357→        if !wait {
   358→            println!("You can check the status with:");
   359→            println!("  gh run list --workflow build_and_release.yml --branch \"{branch}\"",);
   360→            return Ok(());
   361→        }
   362→
   363→        println!("Waiting for build to start...");
   364→
   365→        let mut found_new_run_id: Option<u64> = None;
   366→
   367→        // Poll for up to 30 seconds to find the new run
   368→        for _ in 0..10 {
   369→            std::thread::sleep(std::time::Duration::from_secs(3));
   370→
   371→            let output = Command::new("gh")
   372→                .args([
   373→                    "run",
   374→                    "list",
   375→                    "--workflow",
   376→                    "build_and_release.yml",
   377→                    "--branch",
   378→                    &branch,
   379→                    "--limit",
   380→                    "1",
   381→                    "--json",
   382→                    "databaseId,status,createdAt,headSha",
   383→                ])
   384→                .output()
   385→                .context("Failed to fetch latest run ID")?;
   386→
   387→            if output.status.success() {
   388→                let runs: Vec<serde_json::Value> = serde_json::from_slice(&output.stdout)?;
   389→                if let Some(run) = runs.first() {
   390→                    let status = run["status"].as_str().unwrap_or("");
   391→                    let run_sha = run["headSha"].as_str().unwrap_or("");
   392→                    let id = run["databaseId"].as_u64();
   393→
   394→                    // Ensure we picked up a run for the correct SHA that is active and NEW (id > max_seen_id)
   395→                    if let Some(id) = id
   396→                        && id > max_seen_id
   397→                        && (status == "queued"
   398→                            || status == "in_progress"
   399→                            || status == "requested"
   400→                            || status == "waiting")
   401→                        && run_sha == latest_sha
   402→                    {
   403→                        found_new_run_id = Some(id);
   404→                        break;
   405→                    }
   406→                }
   407→            }
   408→        }
   409→
   410→        found_new_run_id
   411→            .context("Could not find the newly triggered run (or it completed instantly).")?
   412→    };
   413→
   414→    if wait {
   415→        println!("Waiting for Run ID: {run_id_to_watch}...");
   416→        let status = Command::new("gh")
   417→            .args(["run", "watch", &run_id_to_watch.to_string()])
   418→            .status()
   419→            .context("Failed to watch run")?;
   420→
   421→        if status.success() {
   422→            println!("Build completed successfully!");
   423→        } else {
   424→            anyhow::bail!("Build failed or was cancelled.");
   425→        }
   426→    }
   427→
   428→    Ok(())
   429→}
   430→
   431→fn get_artifact_names() -> Result<Vec<String>> {
   432→    let (os, arch) = match env::consts::OS {
   433→        // CI only builds aarch64 for macOS (Apple Silicon)
   434→        "macos" => ("darwin", "aarch64"),
   435→        // For Linux, the CI uses standard architecture names (x86_64, aarch64)
   436→        "linux" => ("linux", env::consts::ARCH),
   437→        // Fallback/Default
   438→        other => {
   439→            anyhow::bail!(
   440→                "Unsupported OS '{other}' for PR build artifacts; only 'macos' and 'linux' are supported",
   441→            );
   442→        }
   443→    };
   444→
   445→    // Prioritize metal for darwin
   446→    let mut names = Vec::new();
   447→    if os == "darwin" {
   448→        names.push(format!("spiced_metal_{os}_{arch}"));
   449→    }
   450→    names.push(format!("spiced_{os}_{arch}"));
   451→
   452→    Ok(names)
   453→}
   454→
   455→#[derive(Deserialize, Debug)]
   456→struct Artifact {
   457→    name: String,
   458→}
   459→
   460→#[derive(Deserialize, Debug)]
   461→struct ArtifactList {
   462→    artifacts: Vec<Artifact>,
   463→}
   464→
   465→#[cfg(unix)]
   466→fn install_build(branch: Option<&str>, pr: Option<u64>) -> Result<()> {
   467→    let branch = resolve_branch_or_pr(branch, pr)?;
   468→    validate_branch_name(&branch)?;
   469→    let repo_owner_name = get_repo_owner_name()?;
   470→
   471→    let target_dir = dirs::home_dir()
   472→        .context("Could not find home directory")?
   473→        .join(".spice/bin")
   474→        .join(&branch);
   475→
   476→    println!("Looking for latest successful build for branch: {branch}...",);
   477→
   478→    let output = Command::new("gh")
   479→        .args([
   480→            "run",
   481→            "list",
   482→            "--workflow",
   483→            "build_and_release.yml",
   484→            "--branch",
   485→            &branch,
   486→            "--status",
   487→            "success",
   488→            "--limit",
   489→            "1",
   490→            "--json",
   491→            "databaseId",
   492→        ])
   493→        .output()
   494→        .context("Failed to execute gh run list")?;
   495→
   496→    if !output.status.success() {
   497→        anyhow::bail!(
   498→            "gh run list failed: {}",
   499→            String::from_utf8_lossy(&output.stderr)
   500→        );
   501→    }
   502→
   503→    let runs: Vec<GhRun> = serde_json::from_slice(&output.stdout)?;
   504→    let run = runs
   505→        .first()
   506→        .context(format!("No successful build found for branch '{branch}'"))?;
   507→    let run_id = run.database_id;
   508→
   509→    println!("Found Run ID: {run_id}");
   510→
   511→    // List artifacts for the run to check which one exists
   512→    println!("Checking available artifacts...");
   513→    let output = Command::new("gh")
   514→        .args([
   515→            "api",
   516→            &format!("repos/{repo_owner_name}/actions/runs/{run_id}/artifacts",),
   517→        ])
   518→        .output()
   519→        .context("Failed to fetch artifacts list")?;
   520→
   521→    if !output.status.success() {
   522→        anyhow::bail!(
   523→            "Failed to list artifacts: {}",
   524→            String::from_utf8_lossy(&output.stderr)
   525→        );
   526→    }
   527→
   528→    let artifact_list: ArtifactList = serde_json::from_slice(&output.stdout)?;
   529→    let available_artifacts: Vec<String> = artifact_list
   530→        .artifacts
   531→        .into_iter()
   532→        .map(|a| a.name)
   533→        .collect();
   534→
   535→    let wanted_artifacts = get_artifact_names()?;
   536→    let artifact_to_download = wanted_artifacts
   537→        .iter()
   538→        .find(|name| available_artifacts.contains(name))
   539→        .context("No compatible artifact found in this build")?;
   540→
   541→    let temp_dir = tempfile::tempdir()?;
   542→    let temp_path = temp_dir.path();
   543→
   544→    println!(
   545→        "Downloading artifact '{}' to {}...",
   546→        artifact_to_download,
   547→        temp_path.display()
   548→    );
   549→
   550→    let status = Command::new("gh")
   551→        .args([
   552→            "run",
   553→            "download",
   554→            &run_id.to_string(),
   555→            "-n",
   556→            artifact_to_download,
   557→            "-D",
   558→        ])
   559→        .arg(temp_path)
   560→        .stdout(Stdio::null())
   561→        .stderr(Stdio::inherit())
   562→        .status()
   563→        .context("Failed to execute gh run download")?;
   564→
   565→    if !status.success() {
   566→        anyhow::bail!("Failed to download artifact");
   567→    }
   568→
   569→    println!("Installing to {}...", target_dir.display());
   570→    fs::create_dir_all(&target_dir)?;
   571→
   572→    // Find tar.gz
   573→    let mut tar_file: Option<PathBuf> = None;
   574→    for entry in fs::read_dir(temp_path)? {
   575→        let entry = entry?;
   576→        let path = entry.path();
   577→        if let Some(ext) = path.extension()
   578→            && ext == "gz"
   579→        {
   580→            tar_file = Some(path);
   581→            break;
   582→        }
   583→    }
   584→
   585→    let tar_file = tar_file.context("No tar.gz file found in downloaded artifact")?;
   586→
   587→    // Extract directly to target location
   588→    let tar_gz = fs::File::open(&tar_file)?;
   589→    let tar = GzDecoder::new(tar_gz);
   590→    let mut archive = Archive::new(tar);
   591→
   592→    // Use a temp file in the target directory for extraction
   593→    let temp_target = target_dir.join("spiced.tmp");
   594→    let mut found_binary = false;
   595→
   596→    for entry in archive.entries()? {
   597→        let mut entry = entry?;
   598→        let path = entry.path()?;
   599→        if path.ends_with("spiced") {
   600→            println!("Extracting binary to {}...", temp_target.display());
   601→            entry.unpack(&temp_target)?;
   602→            found_binary = true;
   603→            break;
   604→        }
   605→    }
   606→
   607→    if !found_binary {
   608→        anyhow::bail!("Could not find 'spiced' binary in archive");
   609→    }
   610→
   611→    let target_binary = target_dir.join("spiced");
   612→
   613→    // Make executable before rename
   614→    let mut perms = fs::metadata(&temp_target)?.permissions();
   615→    perms.set_mode(0o755);
   616→    fs::set_permissions(&temp_target, perms)?;
   617→
   618→    // Rename might fail if cross-device link (EXDEV), so we try copy+remove as fallback
   619→    if let Err(e) = fs::rename(&temp_target, &target_binary) {
   620→        if e.kind() == std::io::ErrorKind::CrossesDevices {
   621→            fs::copy(&temp_target, &target_binary)?;
   622→            let _ = fs::remove_file(&temp_target);
   623→        } else {
   624→            return Err(e.into());
   625→        }
   626→    }
   627→
   628→    println!("Installed spiced to {}", target_binary.display());
   629→
   630→    // Symlink
   631→    let symlink_path = dirs::home_dir()
   632→        .context("Could not find home directory")?
   633→        .join(".spice/bin/spiced-dev");
   634→
   635→    // Remove existing symlink if it exists
   636→    if symlink_path.exists() || fs::symlink_metadata(&symlink_path).is_ok() {
   637→        fs::remove_file(&symlink_path).ok();
   638→    }
   639→
   640→    std::os::unix::fs::symlink(&target_binary, &symlink_path)?;
   641→
   642→    println!(
   643→        "Updated symlink: {} -> {}",
   644→        symlink_path.display(),
   645→        target_binary.display()
   646→    );
   647→    println!(
   648→        "You can now run it comfortably via: {}",
   649→        symlink_path.display()
   650→    );
   651→
   652→    Ok(())
   653→}
   654→
   655→#[cfg(unix)]
   656→fn run_build(
   657→    branch: Option<&str>,
   658→    pr: Option<u64>,
   659→    interactive: bool,
   660→    args: &[String],
   661→) -> Result<()> {
   662→    let branch = if interactive {
   663→        select_branch()?
   664→    } else {
   665→        resolve_branch_or_pr(branch, pr)?
   666→    };
   667→    validate_branch_name(&branch)?;
   668→
   669→    let binary_path = dirs::home_dir()
   670→        .context("Could not find home directory")?
   671→        .join(".spice/bin")
   672→        .join(&branch)
   673→        .join("spiced");
   674→
   675→    if !binary_path.exists() {
   676→        println!(
   677→            "Binary not found at {}. Installing...",
   678→            binary_path.display()
   679→        );
   680→        install_build(Some(&branch), None)?;
   681→    }
   682→
   683→    println!("Running spiced from branch '{branch}'...");
   684→    println!("Exec: {} {}", binary_path.display(), args.join(" "));
   685→
   686→    // Replace the current process with spiced (Unix only)
   687→    let error = Command::new(&binary_path).args(args).exec();
   688→
   689→    // If we're here, exec failed
   690→    anyhow::bail!("Failed to execute spiced: {error}");
   691→}
   692→
   693→#[cfg(unix)]
   694→fn select_branch() -> Result<String> {
   695→    let base_dir = dirs::home_dir()
   696→        .context("Could not find home directory")?
   697→        .join(".spice/bin");
   698→
   699→    if !base_dir.exists() {
   700→        anyhow::bail!("No binaries found in {}", base_dir.display());
   701→    }
   702→
   703→    let mut branches = Vec::new();
   704→
   705→    // Walk directory to find all 'spiced' binaries
   706→    for entry in WalkDir::new(&base_dir).min_depth(1) {
   707→        let entry = entry.ok();
   708→        if let Some(entry) = entry
   709→            && entry.file_type().is_file()
   710→            && entry.file_name() == "spiced"
   711→        {
   712→            // Found a spiced binary, the parent dir is the branch path
   713→            if let Some(branch_dir) = entry.path().parent() {
   714→                // Get relative path from base_dir to get the branch name
   715→                if let Ok(rel_path) = branch_dir.strip_prefix(&base_dir)
   716→                    && let Some(branch_name) = rel_path.to_str()
   717→                    && !branch_name.is_empty()
   718→                {
   719→                    branches.push(branch_name.to_string());
   720→                }
   721→            }
   722→        }
   723→    }
   724→
   725→    if branches.is_empty() {
   726→        anyhow::bail!("No installed branches found in {}", base_dir.display());
   727→    }
   728→
   729→    branches.sort();
   730→
   731→    let selection = dialoguer::Select::new()
   732→        .with_prompt("Select a branch to run")
   733→        .items(&branches)
   734→        .default(0)
   735→        .interact()
   736→        .context("Failed to select branch")?;
   737→
   738→    Ok(branches[selection].clone())
   739→}
   740→

